const config = {
  groupId: 'group_00',
  prefix: 'gesture',
  timeoutMs: 30000,
  adminUsername: 'admin',
  adminPassword: 'admin123'
};
flow.set('gestureConfig', config);
if (msg.status) {
  const text = String(msg.status.text || '').toLowerCase();
  msg.kind = 'broker_status';
  msg.connected = text.includes('connected') && !text.includes('disconnected');
  return [msg, null];
}
msg.kind = 'init';
const topics = [];
for (const nodeId of ['node_01', 'node_02', 'node_03']) {
  topics.push(`${config.prefix}/${config.groupId}/${nodeId}/python/status`);
  topics.push(`${config.prefix}/${config.groupId}/${nodeId}/device/status`);
  topics.push(`${config.prefix}/${config.groupId}/${nodeId}/availability/python`);
  topics.push(`${config.prefix}/${config.groupId}/${nodeId}/availability/esp32`);
}
topics.push(`${config.prefix}/${config.groupId}/node_03/event`);
return [
  msg,
  {action: 'subscribe', topic: topics.map(topic => ({topic, qos: 1}))}
];

const cfg = flow.get('gestureConfig') || {groupId:'group_01',prefix:'gesture',timeoutMs:30000,adminUsername:'admin',adminPassword:'admin123'};
const now = Date.now(), iso = new Date().toISOString();
let profiles = context.get('profiles') || [];
let runtime = context.get('runtime') || {};
let sessions = context.get('sessions') || {};
let controllers = context.get('controllers') || {};
let appModes = context.get('appModes') || {};
for(const group of Object.keys(appModes))if(!['MEDIA_PLAYER','SNAKE_GAME'].includes(appModes[group]))appModes[group]='MEDIA_PLAYER';
let mqttOnline = context.get('mqttOnline') || false;
function save(){context.set('profiles',profiles);context.set('runtime',runtime);context.set('sessions',sessions);context.set('controllers',controllers);context.set('appModes',appModes);context.set('mqttOnline',mqttOnline)}
function sql(op,topic,payload=[],extra={}){return {_op:op,topic,payload,...extra}}
function mqtt(group,node,suffix,payload,retain=false){return {topic:`${cfg.prefix}/${group}/${node}/${suffix}`,payload:JSON.stringify(payload),qos:1,retain}}
function validId(value){return /^[A-Za-z0-9_-]+$/.test(String(value||''))}
function auth(p){const s=sessions[p.session_token];return !!s&&s.client_id===p.client_id&&s.until>now}
function feedback(ok,message,client_id='',extra={}){return {payload:{kind:'feedback',ok,message,client_id,...extra}}}
function profileRow(row){return {group_id:String(row.group_id),node_id:String(row.node_id),nama:String(row.nama||''),nim:String(row.nim||''),kelas:String(row.kelas||''),area:String(row.area||''),foto_base64:String(row.foto_base64||''),active:Number(row.is_active)!==0}}
function profile(group,node){return profiles.find(x=>x.group_id===group&&x.node_id===node)}
function nodeType(node){return node==='node_01'?'TRAFFIC':node==='node_02'?'VIRTUAL_TOUCH':node==='node_03'?'INTERACTIVE':'UNKNOWN'}
function groupRuntime(group){return runtime[group]||(runtime[group]={})}
function nodeRuntime(group,node){const g=groupRuntime(group);return g[node]||(g[node]={})}
function groups(){return [cfg.groupId]}
function nodeSnapshot(group,node){const p=profile(group,node),r=nodeRuntime(group,node),type=nodeType(node);
 const pythonOnline=now-(r.pythonAt||0)<cfg.timeoutMs, espOnline=type==='INTERACTIVE'?false:now-(r.espAt||0)<cfg.timeoutMs;
 const cameraOnline=pythonOnline&&r.python?.camera_online!==false;
 return {group_id:group,node_id:node,type,registered:!!p,active:p?.active??true,nama:p?.nama||'',nim:p?.nim||'',kelas:p?.kelas||'',area:p?.area||'',foto_base64:p?.foto_base64||'',python_online:pythonOnline,camera_online:cameraOnline,esp32_online:espOnline,online:type==='INTERACTIVE'?cameraOnline:(cameraOnline&&espOnline),python:r.python||{},device:r.device||{},last_event:r.lastEvent||null,updated_at:r.updatedAt||null};}
function state(){const gs=groups();const nodes=[];for(const group of gs)for(const node of ['node_01','node_02','node_03'])nodes.push(nodeSnapshot(group,node));return {payload:{kind:'state',group_id:cfg.groupId,mqtt_online:mqttOnline,groups:gs,nodes,app_modes:appModes,controllers:Object.fromEntries(Object.entries(controllers).map(([g,c])=>[g,{active:c.until>now}])),updated_at:iso}}}
function load(extra={}){return sql('load_nodes','SELECT * FROM gesture_nodes WHERE group_id=? ORDER BY node_id',[cfg.groupId],extra)}
function parseMqtt(msg,p){if(typeof msg.topic!=='string')return null;const parts=msg.topic.split('/').filter(Boolean);if(parts.length<4||parts[0]!==cfg.prefix)return null;const group=parts[1],node=parts[2],suffix=parts.slice(3).join('/');if(group!==cfg.groupId||!['node_01','node_02','node_03'].includes(node))return null;if(String(p.group_id||'')!==cfg.groupId||String(p.node_id||'')!==node)return null;return {group:cfg.groupId,node,suffix}}

if(msg.error){const target=msg._feedback?.payload?.client_id||'';return [null,null,null,feedback(false,`Operasi database gagal: ${msg.error.message||'kesalahan SQLite'}`,target)]}

if(msg._op){
 if(msg._op==='create_nodes')return [sql('create_events',`CREATE TABLE IF NOT EXISTS gesture_events(event_id TEXT PRIMARY KEY,group_id TEXT NOT NULL,node_id TEXT NOT NULL,app_mode TEXT,gesture TEXT,action TEXT,event_time TEXT NOT NULL)`),null,null,null];
 if(msg._op==='create_events')return [load(),null,null,null];
 if(msg._op==='load_nodes'){profiles=(Array.isArray(msg.payload)?msg.payload:[]).map(profileRow);save();return [null,null,state(),msg._feedback||null]}
 if(['save_node','delete_node','toggle_node','save_event'].includes(msg._op))return [load(msg._feedback?{_feedback:msg._feedback}:{}),null,null,null];
}
let p=msg.payload;
if(typeof p==='string'||Buffer.isBuffer(p)){try{p=JSON.parse(p.toString())}catch{return null}}
if(!p||typeof p!=='object'||Array.isArray(p))p=msg;
const kind=String(msg.kind||p.kind||'');
if(kind==='init'){runtime={};save();return [sql('create_nodes',`CREATE TABLE IF NOT EXISTS gesture_nodes(group_id TEXT NOT NULL,node_id TEXT NOT NULL,nama TEXT NOT NULL,nim TEXT NOT NULL,kelas TEXT NOT NULL,area TEXT NOT NULL,foto_base64 TEXT NOT NULL DEFAULT '',is_active INTEGER NOT NULL DEFAULT 1,updated_at TEXT DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(group_id,node_id))`),null,null,null]}
if(kind==='broker_status'){mqttOnline=!!msg.connected;save();return [null,null,state(),null]}
if(kind==='tick'){for(const [group,nodes] of Object.entries(runtime))for(const [node,r] of Object.entries(nodes)){if(now-(r.pythonAt||0)>=cfg.timeoutMs)r.pythonOnline=false;if(now-(r.espAt||0)>=cfg.timeoutMs)r.espOnline=false;}for(const [group,c] of Object.entries(controllers))if(c.until<=now)delete controllers[group];save();return [null,null,state(),null]}

const route=parseMqtt(msg,p);
if(route){const r=nodeRuntime(route.group,route.node);r.updatedAt=iso;
 if(route.suffix==='python/status'){r.pythonAt=now;r.python=p;}
 else if(route.suffix==='device/status'){r.espAt=now;r.device=p;}
 else if(route.suffix==='availability/python'){r.pythonAt=p.online===false?0:now;}
 else if(route.suffix==='availability/esp32'){r.espAt=p.online===false?0:now;}
 else if(route.suffix==='event'){
  if(r.lastEvent?.event_id===p.event_id)return null;
  r.lastEvent=p;r.pythonAt=now;save();
  return [sql('save_event','INSERT OR IGNORE INTO gesture_events(event_id,group_id,node_id,app_mode,gesture,action,event_time) VALUES(?,?,?,?,?,?,?)',[String(p.event_id),route.group,route.node,String(p.app_mode||''),String(p.gesture||''),String(p.action||''),String(p.timestamp||iso)]),null,state(),null];
 }else return null;
 save();return [null,null,state(),null];}

if(kind==='request_state')return [null,null,state(),null];
if(kind==='login'){if(p.username===cfg.adminUsername&&p.password===cfg.adminPassword){const token=Math.random().toString(36).slice(2)+Math.random().toString(36).slice(2);sessions[token]={client_id:p.client_id,until:now+8*3600000};save();return [null,null,null,feedback(true,'Login berhasil',p.client_id,{session_token:token})]}return [null,null,null,feedback(false,'Username atau password salah',p.client_id)]}
if(['save_node','delete_node','toggle_node'].includes(kind)&&!auth(p))return [null,null,null,feedback(false,'Sesi admin tidak valid',p.client_id)];
if(kind==='save_node'){
 const group=cfg.groupId,node=String(p.node_id||'');
 if(!['node_01','node_02','node_03'].includes(node))return [null,null,null,feedback(false,'Node ID tidak valid',p.client_id)];
 if(!p.nama||!p.nim||!p.kelas||!p.area||!p.foto_base64)return [null,null,null,feedback(false,'Nama, NIM, kelas, area, dan foto wajib lengkap',p.client_id)];
 const existed=!!profile(group,node),message=existed?`${node} berhasil diperbarui`:`${node} berhasil ditambahkan`;
 return [sql('save_node',`INSERT INTO gesture_nodes(group_id,node_id,nama,nim,kelas,area,foto_base64,is_active) VALUES(?,?,?,?,?,?,?,1) ON CONFLICT(group_id,node_id) DO UPDATE SET nama=excluded.nama,nim=excluded.nim,kelas=excluded.kelas,area=excluded.area,foto_base64=excluded.foto_base64,updated_at=CURRENT_TIMESTAMP`,[group,node,String(p.nama),String(p.nim),String(p.kelas),String(p.area),String(p.foto_base64)],{_feedback:feedback(true,message,p.client_id)}),null,null,null];}
if(kind==='toggle_node')return [sql('toggle_node','UPDATE gesture_nodes SET is_active=?,updated_at=CURRENT_TIMESTAMP WHERE group_id=? AND node_id=?',[p.active?1:0,cfg.groupId,String(p.node_id)],{_feedback:feedback(true,'Status node berhasil diperbarui',p.client_id)}),null,null,null];
if(kind==='delete_node')return [sql('delete_node','DELETE FROM gesture_nodes WHERE group_id=? AND node_id=?',[cfg.groupId,String(p.node_id)],{_feedback:feedback(true,'Data node berhasil dihapus',p.client_id)}),null,null,null];
if(kind==='claim_control'||kind==='control_heartbeat'){
 const group=cfg.groupId;const current=controllers[group];
 if(current&&current.client_id!==p.client_id&&current.until>now)return [null,null,null,feedback(false,'Dashboard kelompok ini sedang dikendalikan browser lain',p.client_id)];
 controllers[group]={client_id:p.client_id,until:now+30000};save();return [null,null,state(),feedback(true,'Kontrol dashboard aktif',p.client_id)];}
if(kind==='release_control'){const group=cfg.groupId;if(controllers[group]?.client_id===p.client_id)delete controllers[group];save();return [null,null,state(),null]}
if(kind==='set_app_mode'){
 const group=cfg.groupId,mode=String(p.app_mode||'');const current=controllers[group];
 if(!current||current.client_id!==p.client_id||current.until<=now)return [null,null,null,feedback(false,'Klaim kontrol dashboard terlebih dahulu',p.client_id)];
 if(!['MEDIA_PLAYER','SNAKE_GAME'].includes(mode))return null;appModes[group]=mode;controllers[group].until=now+30000;save();
 const out=mqtt(group,'node_03','control',{group_id:group,node_id:'node_03',app_mode:mode,controller_id:p.client_id,timestamp:iso},true);
 return [null,out,state(),null];}
return null;

let statement=String(msg.topic||'');
if(!Array.isArray(msg.payload))msg.payload=[];
let index=0;
if(statement.includes('?')){
  statement=statement.replace(/\?/g,()=>'$p'+(++index));
  msg.topic=statement;
}
const placeholders=statement.match(/\$[A-Za-z_][A-Za-z0-9_]*/g)||[];
if(placeholders.length!==msg.payload.length){
  node.error(`Jumlah parameter SQLite tidak cocok: query ${placeholders.length}, data ${msg.payload.length}`,msg);
  return null;
}
return msg;
